R=/scratch/jjyeung/orch_n30
date -u +%TZ
mkdir -p $R/sb_d7bind; cp $R/sb_cursor_probe/AGENTS.md $R/sb_d7bind/AGENTS.md
echo  | base64 -d > $R/sb_d7bind/PROMPT.md
cd $R/sb_d7bind && tmux new-session -d -s sb_d7bind "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
mkdir -p $R/sb_drev8/prompts $R/sb_drev8/out
echo  | base64 -d > $R/sb_drev8/prompts/sb_drev8.md
mkdir -p $R/sb_f64rev2/prompts $R/sb_f64rev2/out
echo  | base64 -d > $R/sb_f64rev2/prompts/sb_f64rev2.md
{ echo sb_drev8; cat $R/sb_queue/queue.txt; echo sb_f64rev2; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt; cat $R/sb_queue/queue.txt | tr "\n" " "; echo
tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "
